# ==============================================================================# 038_TASK_EXECUTOR.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")print("=" * 80)print("TASK EXECUTOR")print("=" * 80)cur.execute("""SELECT *FROM task_queueWHERE status='PENDING'ORDER BYCASE priorityWHEN 'HIGH' THEN 1WHEN 'NORMAL' THEN 2WHEN 'LOW' THEN 3END,id""")tasks = cur.fetchall()executed = 0for task in tasks:    start = datetime.now().isoformat()    cur.execute("""    UPDATE task_queue    SET        status=?,        started_at=?,        finished_at=?    WHERE id=?    """,(        "COMPLETED",        start,        datetime.now().isoformat(),        task["id"]    ))    executed += 1    print(        f"[OK] "        f"{task['priority']:<8}"        f"{task['task_name']:<25}"        f"{task['origin']}"    )conn.commit()print("=" * 80)cur.execute("""SELECTCOUNT(*)FROM task_queueWHERE status='COMPLETED'""")completed = cur.fetchone()[0]cur.execute("""SELECTCOUNT(*)FROM task_queueWHERE status='PENDING'""")pending = cur.fetchone()[0]print(f"TAREFAS EXECUTADAS : {executed}")print(f"TOTAL COMPLETADAS  : {completed}")print(f"PENDENTES          : {pending}")print("=" * 80)conn.close()

